package dev.veltraph.client.foraging.supply;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import dev.veltraph.client.world.BlockPos;
/** Compiles against unchanged CU; proves its unconditional cursor veto rejects one owned issued prediction. */
final class ForagingOwnedPredictionRuntimeTest {
    @Test void issuedPurchasePredictionKeepsOriginalDeadlineWithoutSecondDispatch(){var player=new Object();var world=new Object();var connection=new Object();var menu=new Object();var scope=new ForagingSupplyRuntime.Scope(player,world,connection);var items=Collections.nCopies(36,ForagingSupplyRuntime.Stack.EMPTY);var resource=new ForagingSupplyBindings.Resource("minecraft:bone_meal","Bone Meal","bone",64,"shop","Supply","Offer","offer",10,"Purse:");var b=new ForagingSupplyBindings(1,new BlockPos(0,70,0),new BlockPos(1,70,0),"Chest",Map.of(ForagingSupplyConfig.Type.BONEMEAL,resource,ForagingSupplyConfig.Type.SAPLING,resource),1000);class Port implements ForagingSupplyRuntime.Port{int dispatched;public boolean acquire(ForagingSupplyRuntime.Observation o,ForagingSupplyBindings.Resource r){dispatched++;return true;}public boolean open(ForagingSupplyRuntime.Observation o){return true;}public boolean store(ForagingSupplyRuntime.Observation o,int index){return false;}public boolean verifyStorage(ForagingSupplyRuntime.Observation o){return false;}public boolean ownedPurchasePrediction(ForagingSupplyRuntime.Observation o){return o.menu()==menu;}public void release(){}}var port=new Port();var runtime=new ForagingSupplyRuntime();runtime.start(new ForagingSupplyRuntime.Observation(scope,10,items,true,true,100,null,"",List.of(),true,false),b,ForagingSupplyConfig.Type.BONEMEAL);runtime.tick(new ForagingSupplyRuntime.Observation(scope,11,items,true,true,100,null,"",List.of(),true,false),port);runtime.tick(new ForagingSupplyRuntime.Observation(scope,12,items,false,true,100,menu,"Supply",List.of(),true,false),port);assertEquals(ForagingSupplyRuntime.Stage.ACQUIRE_ACK,runtime.stage());assertEquals(1,port.dispatched);runtime.tick(new ForagingSupplyRuntime.Observation(scope,1010,items,false,true,100,menu,"Supply",List.of(),true,false),port);assertEquals(ForagingSupplyRuntime.Stage.UNKNOWN,runtime.stage());assertEquals(1,port.dispatched);}
}
